describe("mesh-scalus-emulator", () => {
  it("calculates fees from script vote proposal correctly", async () => {
    const initialUtxos = [
      {
        input: {
          txHash:
            "565d611be830b31c636b594f942817a93100832b888fbaff0c868ae1f7340aef",
          outputIndex: 0,
        },
        output: {
          address:
            "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
          amount: [{ unit: "lovelace", quantity: "10000000000" }],
        },
      },
      {
        input: {
          txHash:
            "66b98c314f5fec34e44099b3772cadcdd47083ea4bd15d4d47307addf59ddd10",
          outputIndex: 0,
        },
        output: {
          address:
            "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
          amount: [{ unit: "lovelace", quantity: "500000000" }],
        },
      },
      {
        input: {
          txHash:
            "66b98c314f5fec34e44099b3772cadcdd47083ea4bd15d4d47307addf59ddd10",
          outputIndex: 1,
        },
        output: {
          address:
            "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
          amount: [{ unit: "lovelace", quantity: "53092243057" }],
        },
      },
      {
        input: {
          txHash:
            "66b98c314f5fec34e44099b3772cadcdd47083ea4bd15d4d47307addf59ddd10",
          outputIndex: 2,
        },
        output: {
          address:
            "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
          amount: [{ unit: "lovelace", quantity: "26546211847" }],
        },
      },
      {
        input: {
          txHash:
            "66b98c314f5fec34e44099b3772cadcdd47083ea4bd15d4d47307addf59ddd10",
          outputIndex: 3,
        },
        output: {
          address:
            "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
          amount: [{ unit: "lovelace", quantity: "13273105924" }],
        },
      },
      {
        input: {
          txHash:
            "66b98c314f5fec34e44099b3772cadcdd47083ea4bd15d4d47307addf59ddd10",
          outputIndex: 4,
        },
        output: {
          address:
            "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
          amount: [{ unit: "lovelace", quantity: "13273105924" }],
        },
      },
      {
        input: {
          txHash:
            "66b98c314f5fec34e44099b3772cadcdd47083ea4bd15d4d47307addf59ddd10",
          outputIndex: 5,
        },
        output: {
          address:
            "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
          amount: [{ unit: "lovelace", quantity: "5000000" }],
        },
      },
    ];

    const guardrailsScript = {
      type: "PlutusScriptV3",
      description: "",
      cborHex:
        "",
    };
    const proposal: GovernanceAction = {
      kind: "TreasuryWithdrawalsAction",
      action: {
        withdrawals: {
          stake_test1uq78nhezyyr47v3j0wlj42xvcg4n627rz6c8dejja65m9ng7z899t:
            "10",
        },
        policyHash: {
          bytes: "fa24fb305126805cf2164c161d852a0e7330cf988f1fe558cf7d4a64",
        },
      },
    };
    const txBuilder = new MeshTxBuilder({});
    const txHex = await txBuilder
      .selectUtxosFrom(initialUtxos)
      .txInCollateral(
        initialUtxos[0]!.input.txHash,
        initialUtxos[0]!.input.outputIndex,
        initialUtxos[0]!.output.amount,
        initialUtxos[0]!.output.address,
      )
      .proposal(
        proposal,
        {
          anchorUrl: "ipfs://Qmca3PC1bbHWAKu93nXZit4vTvWzp3zvChnf6QBbSqJCpT",
          anchorDataHash:
            "566e486264b960ac0a36f6824db5d803177cca5cbc642869a31d23cc68c6a839",
        },
        "stake_test1uq78nhezyyr47v3j0wlj42xvcg4n627rz6c8dejja65m9ng7z899t",
        String(100_000_000_000),
      )
      .proposalScript(applyCborEncoding(guardrailsScript.cborHex), "V3")
      .proposalRedeemerValue(0)
      .changeAddress(
        "addr_test1qrzp76pjtwdfzd0dmcceapsu9ejy8aenljmlls4ltxaysx3u080jygg8tuery7al925ves3t854ux94swmn99m4fktxsajvrd7",
      )
      .setCostModels([
        PlutusV1CostModels,
        PlutusV2CostModels,
        PlutusV3CostModels,
      ])
      .complete();

    const tx = Transaction.fromCbor(txHex);
    expect(tx.body().fee().valueOf()).toBeGreaterThan(900000);
  });
});
